using System.Text.Json;
using Midnight.Shared.Http;

namespace Midnight.Demon.Core.Configuration;

/// <summary>Demon configuration, stored in /etc/midnight/config.json and generated by the panel setup page</summary>
public class DemonConfiguration
{
    public const string DefaultPath = "/etc/midnight/config.json";

    public string PanelUrl { get; set; } = "http://localhost:5220";

    public string TokenId { get; set; } = "";

    /// <summary>Node token used for panel &lt;-&gt; demon requests and to verify browser websocket tokens. Never logged.</summary>
    public string Token { get; set; } = "";

    public int HttpPort { get; set; } = 8080;
    public int SftpPort { get; set; } = 2022;

    public string DataPath { get; set; } = "/var/lib/midnight";

    /// <summary>Docker engine endpoint, e.g. unix:///var/run/docker.sock</summary>
    public string DockerSocket { get; set; } = "unix:///var/run/docker.sock";

    public SslConfiguration Ssl { get; set; } = new();

    /// <summary>How server containers are run</summary>
    public ServerRuntimeConfiguration Servers { get; set; } = new();

    /// <summary>Limits of the file manager, archives and backups</summary>
    public FilesConfiguration Files { get; set; } = new();

    public static DemonConfiguration Load(string path)
    {
        if (!File.Exists(path))
            throw new FileNotFoundException($"Demon configuration not found at '{path}'. Copy it from the node setup page in the panel.", path);

        return JsonSerializer.Deserialize<DemonConfiguration>(File.ReadAllText(path), JsonDefaults.Options)
               ?? throw new InvalidOperationException($"Demon configuration at '{path}' is empty");
    }

    /// <summary>Returns a list of problems that prevent the demon from starting</summary>
    public List<string> Validate()
    {
        var errors = new List<string>();

        if (!Uri.TryCreate(PanelUrl, UriKind.Absolute, out var panelUri) || (panelUri.Scheme != "http" && panelUri.Scheme != "https"))
            errors.Add("PanelUrl must be an absolute http(s) url");

        if (string.IsNullOrWhiteSpace(TokenId) || string.IsNullOrWhiteSpace(Token))
            errors.Add("TokenId and Token are required");

        if (HttpPort is < 1 or > 65535)
            errors.Add("HttpPort must be between 1 and 65535");

        if (SftpPort is < 1 or > 65535)
            errors.Add("SftpPort must be between 1 and 65535");

        if (string.IsNullOrWhiteSpace(DataPath) || !Path.IsPathRooted(DataPath))
            errors.Add("DataPath must be an absolute path");

        if (!Uri.TryCreate(DockerSocket, UriKind.Absolute, out _))
            errors.Add("DockerSocket must be an absolute uri like unix:///var/run/docker.sock");

        if (Ssl.Enabled && (string.IsNullOrWhiteSpace(Ssl.CertificatePath) || string.IsNullOrWhiteSpace(Ssl.KeyPath)))
            errors.Add("Ssl.CertificatePath and Ssl.KeyPath are required when ssl is enabled");

        if (Servers.StopTimeoutSeconds is < 1 or > 3600)
            errors.Add("Servers.StopTimeoutSeconds must be between 1 and 3600");

        if (Servers.DiskCheckIntervalSeconds is < 5 or > 3600)
            errors.Add("Servers.DiskCheckIntervalSeconds must be between 5 and 3600");

        if (Servers.DefaultPidLimit < 0)
            errors.Add("Servers.DefaultPidLimit must not be negative");

        if (!string.IsNullOrEmpty(Servers.ContainerUser) && !ServerRuntimeConfiguration.TryParseUser(Servers.ContainerUser, out _, out _))
            errors.Add("Servers.ContainerUser must look like uid:gid, e.g. 988:988 (empty = image default)");

        if (Files.MaxUploadBytes < 1)
            errors.Add("Files.MaxUploadBytes must be positive");

        if (Files.ArchiveTimeoutSeconds is < 10 or > 86_400)
            errors.Add("Files.ArchiveTimeoutSeconds must be between 10 and 86400");

        if (Files.PullTimeoutSeconds is < 10 or > 86_400)
            errors.Add("Files.PullTimeoutSeconds must be between 10 and 86400");

        if (Files.MaxConcurrentPulls is < 1 or > 100)
            errors.Add("Files.MaxConcurrentPulls must be between 1 and 100");

        return errors;
    }
}

public class FilesConfiguration
{
    /// <summary>Largest request body of an upload or a file write (all files of one upload together), default 1 GiB</summary>
    public long MaxUploadBytes { get; set; } = 1024L * 1024 * 1024;

    /// <summary>Compress and decompress are aborted after this many seconds</summary>
    public int ArchiveTimeoutSeconds { get; set; } = 1800;

    /// <summary>A download from a url (pull) is aborted after this many seconds</summary>
    public int PullTimeoutSeconds { get; set; } = 3600;

    /// <summary>How many downloads from urls may run at the same time per server</summary>
    public int MaxConcurrentPulls { get; set; } = 3;
}

public class ServerRuntimeConfiguration
{
    /// <summary>Seconds a server gets to stop gracefully before it is killed</summary>
    public int StopTimeoutSeconds { get; set; } = 60;

    /// <summary>How often the disk usage of every volume is measured</summary>
    public int DiskCheckIntervalSeconds { get; set; } = 60;

    /// <summary>Pids limit of a container when the shard does not set one, 0 = unlimited</summary>
    public int DefaultPidLimit { get; set; } = 512;

    /// <summary>
    /// uid:gid the server container runs as. The volume is chowned to it after the installation and before every start.
    /// Empty = the user of the image and no chown.
    /// </summary>
    public string ContainerUser { get; set; } = "988:988";

    /// <summary>Chown the whole volume before every start (otherwise only after the installation)</summary>
    public bool FixPermissionsOnStart { get; set; } = true;

    /// <summary>The install container gets at least this much memory in MiB</summary>
    public int InstallMinimumMemory { get; set; } = 1024;

    internal static bool TryParseUser(string value, out uint uid, out uint gid)
    {
        uid = gid = 0;
        var parts = value.Split(':');

        return parts.Length == 2 && uint.TryParse(parts[0], out uid) && uint.TryParse(parts[1], out gid);
    }
}

public class SslConfiguration
{
    public bool Enabled { get; set; }
    public string CertificatePath { get; set; } = "";
    public string KeyPath { get; set; } = "";
}
